# Generated by runa via A2A Mesh delegation
"""
Keepalive ping batchelése — minden peer 3 másodpercenként üzenetét aggregálni
egy bulk-msg-be → -70% felesleges TCP connect.

Ez a modul egy KeepaliveBatcher osztályt valósít meg, amely:
  - Gyűjti a peer-ek keepalive ping üzeneteit egy időablak alatt
  - 3 másodpercenként egyetlen bulk üzenetbe aggregálja őket
  - Egyetlen TCP kapcsolaton küldi el a batch-elt üzenetet
  - A fogadó oldalon szétszedi a bulk üzenetet és feldolgozza az egyes ping-eket

Futtatható demo: elindít egy szervert és több klienst, majd bemutatja
a batchelés működését és a TCP kapcsolat csökkenést.
"""

import socket
import threading
import time
import json
import struct
import logging
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple
from collections import defaultdict
import uuid

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(threadName)s] %(levelname)s: %(message)s",
)
logger = logging.getLogger("keepalive_batcher")

# ── Protokoll segédfüggvények ──────────────────────────────────────────────

def send_msg(sock: socket.socket, data: bytes) -> None:
    """Hossz-prefixelt üzenet küldése (4 byte big-endian length + payload)."""
    header = struct.pack(">I", len(data))
    sock.sendall(header + data)


def recv_msg(sock: socket.socket) -> Optional[bytes]:
    """Hossz-prefixelt üzenet fogadása. None ha a kapcsolat lezárult."""
    header = _recv_exact(sock, 4)
    if header is None:
        return None
    (length,) = struct.unpack(">I", header)
    if length == 0:
        return b""
    payload = _recv_exact(sock, length)
    return payload


def _recv_exact(sock: socket.socket, n: int) -> Optional[bytes]:
    """Pontosan n byte fogadása."""
    buf = bytearray()
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk:
            return None
        buf.extend(chunk)
    return bytes(buf)


# ── Adatstruktúrák ─────────────────────────────────────────────────────────

@dataclass
class PingMessage:
    """Egyetlen keepalive ping üzenet egy peer-től."""
    peer_id: str
    timestamp: float
    status: str = "alive"
    metadata: Dict = field(default_factory=dict)

    def to_dict(self) -> dict:
        return {
            "peer_id": self.peer_id,
            "timestamp": self.timestamp,
            "status": self.status,
            "metadata": self.metadata,
        }

    @staticmethod
    def from_dict(d: dict) -> "PingMessage":
        return PingMessage(
            peer_id=d["peer_id"],
            timestamp=d["timestamp"],
            status=d.get("status", "alive"),
            metadata=d.get("metadata", {}),
        )


@dataclass
class BulkPingMessage:
    """
    Több ping üzenet aggregált csomagja.
    Ez az, ami egyetlen TCP kapcsolaton utazik a batchelés után.
    """
    batch_id: str
    pings: List[PingMessage]
    created_at: float

    def to_dict(self) -> dict:
        return {
            "type": "bulk_ping",
            "batch_id": self.batch_id,
            "created_at": self.created_at,
            "pings": [p.to_dict() for p in self.pings],
        }

    def serialize(self) -> bytes:
        return json.dumps(self.to_dict()).encode("utf-8")

    @staticmethod
    def from_dict(d: dict) -> "BulkPingMessage":
        return BulkPingMessage(
            batch_id=d["batch_id"],
            created_at=d["created_at"],
            pings=[PingMessage.from_dict(p) for p in d["pings"]],
        )

    @staticmethod
    def deserialize(data: bytes) -> "BulkPingMessage":
        return BulkPingMessage.from_dict(json.loads(data.decode("utf-8")))


# ── KeepaliveBatcher (küldő oldal) ─────────────────────────────────────────

class KeepaliveBatcher:
    """
    Összegyűjti a ping üzeneteket és batch-enként küldi el.

    Minden BATCH_INTERVAL másodpercenként (alapértelmezett 3s) létrehoz egy
    BulkPingMessage-t a felgyűlt ping-ekből és egyetlen TCP kapcsolaton
    elküldi a cél peer-nek.

    Használat:
        batcher = KeepaliveBatcher(host="127.0.0.1", port=9999)
        batcher.start()
        batcher.add_ping(PingMessage(peer_id="agent_1", timestamp=time.time()))
        ...
        batcher.stop()
    """

    def __init__(
        self,
        host: str = "127.0.0.1",
        port: int = 9999,
        batch_interval: float = 3.0,
        max_batch_size: int = 100,
    ):
        self.host = host
        self.port = port
        self.batch_interval = batch_interval
        self.max_batch_size = max_batch_size

        self._pending: List[PingMessage] = []
        self._lock = threading.Lock()
        self._flush_event = threading.Event()
        self._running = False
        self._thread: Optional[threading.Thread] = None

        # Statisztikák
        self.stats = {
            "total_pings_sent": 0,
            "total_batches_sent": 0,
            "total_tcp_connections": 0,
            "pings_without_batching": 0,  # ha nem lenne batchelés
        }

    def start(self) -> None:
        if self._running:
            return
        self._running = True
        self._thread = threading.Thread(
            target=self._batch_loop, name="BatcherLoop", daemon=True
        )
        self._thread.start()
        logger.info(
            "KeepaliveBatcher elindítva: %s:%d, batch_interval=%.1fs",
            self.host, self.port, self.batch_interval,
        )

    def stop(self) -> None:
        self._running = False
        self._flush_event.set()
        if self._thread:
            self._thread.join(timeout=5)
        # Utolsó flush
        self._flush()
        logger.info("KeepaliveBatcher leállítva. Statisztika: %s", self.stats)

    def add_ping(self, ping: PingMessage) -> None:
        """Hozzáad egy ping üzenetet a batchelési sorhoz."""
        with self._lock:
            self._pending.append(ping)
            self.stats["pings_without_batching"] += 1
            if len(self._pending) >= self.max_batch_size:
                self._flush_event.set()

    def _batch_loop(self) -> None:
        """Fő ciklus: vár a batch_interval-ra vagy flush event-re, majd küld."""
        while self._running:
            if self._flush_event.wait(timeout=self.batch_interval):
                self._flush_event.clear()
            self._flush()

    def _flush(self) -> None:
        """Elküldi a felgyűlt ping-eket egy bulk üzenetben."""
        with self._lock:
            if not self._pending:
                return
            pings_to_send = list(self._pending)
            self._pending.clear()

        bulk = BulkPingMessage(
            batch_id=str(uuid.uuid4()),
            pings=pings_to_send,
            created_at=time.time(),
        )

        try:
            self._send_bulk(bulk)
            self.stats["total_pings_sent"] += len(pings_to_send)
            self.stats["total_batches_sent"] += 1
            self.stats["total_tcp_connections"] += 1
            logger.info(
                "Bulk ping elküldve: batch_id=%s, ping_count=%d",
                bulk.batch_id, len(pings_to_send),
            )
        except Exception as e:
            logger.error("Hiba bulk ping küldésekor: %s", e)
            # Visszatesszük a sorba ha nem sikerült
            with self._lock:
                self._pending = pings_to_send + self._pending

    def _send_bulk(self, bulk: BulkPingMessage) -> None:
        """Egyetlen TCP kapcsolaton elküldi a bulk üzenetet."""
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(5.0)
        try:
            sock.connect((self.host, self.port))
            send_msg(sock, bulk.serialize())
            # Várunk ACK-ra
            ack = recv_msg(sock)
            if ack:
                ack_data = json.loads(ack.decode("utf-8"))
                logger.debug("ACK megkapva: %s", ack_data)
        finally:
            sock.close()


# ── KeepaliveBatchReceiver (fogadó oldal) ──────────────────────────────────

class KeepaliveBatchReceiver:
    """
    TCP szerver, ami fogadja a bulk ping üzeneteket és szétszedi őket.

    Minden beérkező bulk üzenetet feldolgoz: az egyes ping-eket
    frissíti a peer státusz regiszterben.

    Használat:
        receiver = KeepaliveBatchReceiver(host="127.0.0.1", port=9999)
        receiver.start()
        ...
        receiver.stop()
        alive_peers = receiver.get_alive_peers()
    """

    def __init__(self, host: str = "127.0.0.1", port: int = 9999):
        self.host = host
        self.port = port
        self._running = False
        self._server_sock: Optional[socket.socket] = None
        self._thread: Optional[threading.Thread] = None

        # peer_id -> (last_ping_time, status)
        self._peer_registry: Dict[str, Tuple[float, str]] = {}
        self._registry_lock = threading.Lock()

        self.stats = {
            "total_pings_received": 0,
            "total_batches_received": 0,
            "total_tcp_connections_accepted": 0,
        }

    def start(self) -> None:
        if self._running:
            return
        self._server_sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._server_sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._server_sock.bind((self.host, self.port))
        self._server_sock.listen(16)
        self._running = True
        self._thread = threading.Thread(
            target=self._accept_loop, name="ReceiverAccept", daemon=True
        )
        self._thread.start()
        logger.info(
            "KeepaliveBatchReceiver elindítva: %s:%d", self.host, self.port
        )

    def stop(self) -> None:
        self._running = False
        if self._server_sock:
            self._server_sock.close()
        if self._thread:
            self._thread.join(timeout=5)
        logger.info(
            "KeepaliveBatchReceiver leállítva. Statisztika: %s", self.stats
        )

    def _accept_loop(self) -> None:
        while self._running:
            try:
                conn, addr = self._server_sock.accept()
                self.stats["total_tcp_connections_accepted"] += 1
                t = threading.Thread(
                    target=self._handle_connection,
                    args=(conn, addr),
                    name=f"Conn-{addr[1]}",
                    daemon=True,
                )
                t.start()
            except OSError:
                break

    def _handle_connection(self, conn: socket.socket, addr: Tuple) -> None:
        try:
            data = recv_msg(conn)
            if data is None:
                return
            msg_dict = json.loads(data.decode("utf-8"))
            if msg_dict.get("type") != "bulk_ping":
                logger.warning("Ismeretlen üzenet típus: %s", msg_dict.get("type"))
                return

            bulk = BulkPingMessage.from_dict(msg_dict)
            self._process_bulk(bulk)

            # ACK küldése
            ack = json.dumps({
                "type": "bulk_ping_ack",
                "batch_id": bulk.batch_id,
                "processed": len(bulk.pings),
            }).encode("utf-8")
            send_msg(conn, ack)
        except Exception as e:
            logger.error("Hiba kapcsolat kezelésekor: %s", e)
        finally:
            conn.close()

    def _process_bulk(self, bulk: BulkPingMessage) -> None:
        """Feldolgozza a bulk üzenetet: frissíti a peer regisztert."""
        with self._registry_lock:
            for ping in bulk.pings:
                self._peer_registry[ping.peer_id] = (ping.timestamp, ping.status)

        self.stats["total_pings_received"] += len(bulk.pings)
        self.stats["total_batches_received"] += 1
        logger.info(
            "Bulk ping feldolgozva: batch_id=%s, ping_count=%d, peers=%s",
            bulk.batch_id, len(bulk.pings),
            [p.peer_id for p in bulk.pings],
        )

    def get_alive_peers(self) -> List[str]:
        """Visszaadja az élő peer-ek ID-ját."""
        with self._registry_lock:
            return [
                pid for pid, (_, status) in self._peer_registry.items()
                if status == "alive"
            ]

    def get_peer_status(self, peer_id: str) -> Optional[Tuple[float, str]]:
        with self._registry_lock:
            return self._peer_registry.get(peer_id)


# ── Demo: szerver + több kliens batcheléssel ───────────────────────────────

def run_demo():
    """
    Bemutatja a keepalive ping batchelés működését.

    1. Elindít egy KeepaliveBatchReceiver-t (TCP szerver)
    2. Elindít több KeepaliveBatcher-t (különböző peer-ek)
    3. Minden peer 0.5 másodpercenként generál ping-et
    4. A batcher 3 másodpercenként aggregálja és elküldi
    5. Összehasonlítja: batchelt vs. nem-batchelt TCP kapcsolatok száma
    """
    HOST = "127.0.0.1"
    PORT = 19999
    BATCH_INTERVAL = 3.0
    DEMO_DURATION = 10.0  # másodperc
    NUM_PEERS = 5
    PING_RATE = 2.0  # ping / másodperc / peer

    print("=" * 70)
    print("  Keepalive Ping Batchelés Demo")
    print("  Ötlet: minden peer 3s üzenetét aggregálni egy bulk-msg-be")
    print("  Várható: -70% felesleges TCP connect")
    print("=" * 70)

    # --- Szerver indítása ---
    receiver = KeepaliveBatchReceiver(host=HOST, port=PORT)
    receiver.start()
    time.sleep(0.3)

    # --- Kliens batcher-ek indítása ---
    batchers: List[KeepaliveBatcher] = []
    for i in range(NUM_PEERS):
        b = KeepaliveBatcher(
            host=HOST, port=PORT, batch_interval=BATCH_INTERVAL
        )
        b.start()
        batchers.append(b)

    time.sleep(0.3)

    # --- Ping generálás ---
    stop_flag = threading.Event()

    def ping_generator(peer_id: str, batcher: KeepaliveBatcher):
        interval = 1.0 / PING_RATE
        while not stop_flag.is_set():
            ping = PingMessage(
                peer_id=peer_id,
                timestamp=time.time(),
                status="alive",
                metadata={"load": 0.5, "queue_len": 3},
            )
            batcher.add_ping(ping)
            stop_flag.wait(interval)

    generators: List[threading.Thread] = []
    for i, batcher in enumerate(batchers):
        peer_id = f"agent_{i:02d}"
        t = threading.Thread(
            target=ping_generator,
            args=(peer_id, batcher),
            name=f"PingGen-{peer_id}",
            daemon=True,
        )
        t.start()
        generators.append(t)

    # --- Várakozás ---
    print(f"\nDemo fut {DEMO_DURATION:.0f} másodpercig...")
    print(f"  Peerek száma: {NUM_PEERS}")
    print(f"  Ping ráta: {PING_RATE} ping/s/peer")
    print(f"  Batch interval: {BATCH_INTERVAL}s")
    print(f"  Elmélet ping-ek (batchelés nélkül): "
          f"{int(NUM_PEERS * PING_RATE * DEMO_DURATION)} TCP connect")
    print()

    time.sleep(DEMO_DURATION)

    # --- Leállítás ---
    stop_flag.set()
    for t in generators:
        t.join(timeout=2)

    for b in batchers:
        b.stop()
    receiver.stop()

    # --- Eredmények ---
    total_pings_generated = sum(b.stats["pings_without_batching"] for b in batchers)
    total_tcp_with_batching = sum(b.stats["total_tcp_connections"] for b in batchers)
    total_tcp_without_batching = total_pings_generated  # minden ping = 1 TCP connect

    reduction = 0
    if total_tcp_without_batching > 0:
        reduction = (1 - total_tcp_with_batching / total_tcp_without_batching) * 100

    print()
    print("=" * 70)
    print("  EREDMÉNYEK")
    print("=" * 70)
    print(f"  Összes ping generálva:        {total_pings_generated}")
    print(f"  TCP connect (batchelés NÉLKÜL): {total_tcp_without_batching}")
    print(f"  TCP connect (batcheléssel):     {total_tcp_with_batching}")
    print(f"  TCP kapcsolat csökkenés:        {reduction:.1f}%")
    print()
    print(f"  Fogadó oldalon:")
    print(f"    Batch-ek fogadva:     {receiver.stats['total_batches_received']}")
    print(f"    Ping-ek feldolgozva:  {receiver.stats['total_pings_received']}")
    print(f"    Élő peer-ek:          {receiver.get_alive_peers()}")
    print()

    # Per-batcher statisztika
    for i, b in enumerate(batchers):
        print(f"  Batcher {i} (agent_{i:02d}): "
              f"ping-ek={b.stats['total_pings_sent']}, "
              f"batch-ek={b.stats['total_batches_sent']}, "
              f"TCP={b.stats['total_tcp_connections']}")

    print()
    if reduction >= 70:
        print(f"  ✓ Cél elérve: -{reduction:.0f}% TCP connect (cél: -70%)")
    else:
        print(f"  ~ TCP csökkenés: -{reduction:.0f}% (cél: -70%)")
        print(f"    Megjegyzés: hosszabb futtatás esetén a csökkenés növekszik,")
        print(f"    mert a batch_interval fix, de több ping gyűlik össze.")
    print("=" * 70)


if __name__ == "__main__":
    run_demo()